import sys

def is_palindrome(s):
    return s == s[::-1]

def process_string(s):
    n = len(s)
    for i in range(n):
        new_s = s[:i] + 'a' + s[i:]
        if not is_palindrome(new_s):
            return "YES\n" + new_s
    new_s = s + 'a'
    if not is_palindrome(new_s):
        return "YES\n" + new_s
    return "NO"

input = sys.stdin.read().splitlines()
t = int(input[0])
results = []
for i in range(1, t + 1):
    results.append(process_string(input[i]))
sys.stdout.write('\n'.join(results))
